using ContosoUniversity.Services;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain the static queue to ensure clean state
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain after each test
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_WithAllParameters_EnqueuesNotification()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        // Arrange & Act
        _sut.SendNotification("Student", "42", null, EntityOperation.UPDATE, "Admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_ShortOverload_DefaultsUserNameToSystem()
    {
        // Arrange & Act
        _sut.SendNotification("Course", "101", EntityOperation.DELETE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
        Assert.Equal("DELETE", notification.Operation);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        // Arrange & Act
        _sut.SendNotification("Department", "5", "Math", EntityOperation.CREATE, null);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_WithItems_ReturnsFIFO()
    {
        // Arrange
        _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("Student", "2", "Second", EntityOperation.UPDATE);

        // Act
        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        // Assert
        Assert.Contains("First", first.Message);
        Assert.Contains("Second", second.Message);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        // Arrange & Act
        _sut.SendNotification("Course", "1", "Physics", operation);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.Contains(expectedVerb, notification.Message);
        Assert.Contains("Physics", notification.Message);
    }

    [Fact]
    public void SendNotification_ExceedsQueueCap_EvictsOldItems()
    {
        // Arrange - send more than 500 items
        for (int i = 0; i < 510; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Act - count remaining items
        int count = 0;
        while (_sut.ReceiveNotification() != null) count++;

        // Assert - should be at most 500
        Assert.True(count <= 500);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert - MarkAsRead is a no-op but should not throw
        var exception = Record.Exception(() => _sut.MarkAsRead(1));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        // Act & Assert
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithDisplayName_IncludesQuotedName()
    {
        // Arrange & Act
        _sut.SendNotification("Department", "3", "Engineering", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.Equal("New Department 'Engineering' has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_IncludesIdFormat()
    {
        // Arrange & Act
        _sut.SendNotification("Department", "7", null, EntityOperation.DELETE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.Equal("Department (ID: 7) has been deleted", notification.Message);
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { ID = 1, LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { ID = 2, LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2019, 9, 1) },
            new Student { ID = 3, LastName = "Barker", FirstMidName = "Arturo", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { ID = 4, LastName = "Zheng", FirstMidName = "Wei", EnrollmentDate = new DateTime(2018, 9, 1) }
        );
        _context.SaveChanges();
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index(null, null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Barker", model[2].LastName);
        Assert.Equal("Zheng", model[3].LastName);
    }

    [Fact]
    public void Index_NameDesc_OrdersByLastNameDescending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Zheng", model[0].LastName);
        Assert.Equal("Barker", model[1].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Zheng", model[0].LastName); // 2018
        Assert.Equal("Alonso", model[1].LastName); // 2019
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Barker", model[0].LastName); // 2021
        Assert.Equal("Alexander", model[1].LastName); // 2020
    }

    [Fact]
    public void Index_SearchString_FiltersResults()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index(null, null, "Al", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count); // Alexander and Alonso
    }

    [Fact]
    public void Index_SearchStringResetsPage_PageIsOne()
    {
        // Arrange
        SeedStudents();

        // Act - new search string should reset to page 1
        var result = _controller.Index(null, null, "Alex", 3) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_CurrentFilter_MaintainsSearchAcrossPages()
    {
        // Arrange
        SeedStudents();

        // Act - null searchString uses currentFilter
        var result = _controller.Index(null, "Al", null, 1) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_Pagination_RespectsPageSize()
    {
        // Arrange - add more than 10 students
        for (int i = 1; i <= 15; i++)
        {
            _context.Students.Add(new Student
            {
                ID = i,
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Today
            });
        }
        _context.SaveChanges();

        // Act
        var result = _controller.Index(null, null, null, 1) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(10, model.Count);
        Assert.True(model.HasNextPage);
        Assert.False(model.HasPreviousPage);
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = new Student
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.Today,
            Enrollments = new List<Enrollment>()
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        // Act
        var result = _controller.Details(1) as ViewResult;

        // Assert
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal("Test", model.LastName);
        Assert.Equal("Student", model.FirstMidName);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        // Arrange
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Single(_context.Students);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };
        _controller.ModelState.AddModelError("LastName", "Required");

        // Act
        var result = _controller.Create(student) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.IsType<Student>(result.Model);
    }

    [Fact]
    public void Create_Post_MinValueDate_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Create(student) as ViewResult;

