using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Concrete controller to test BaseController behavior
/// </summary>
public class TestableController : BaseController
{
    public TestableController(SchoolContext context) : base(context) { }

    public void CallSendEntityNotification(string entityType, string entityId, EntityOperation operation)
    {
        SendEntityNotification(entityType, entityId, operation);
    }

    public void CallSendEntityNotification(string entityType, string entityId, string displayName, EntityOperation operation)
    {
        SendEntityNotification(entityType, entityId, displayName, operation);
    }
}

public class BaseControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly TestableController _controller;

    public BaseControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new TestableController(_context);
        // Drain queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void SendEntityNotification_Success_EnqueuesNotification()
    {
        // Act
        _controller.CallSendEntityNotification("Student", "42", "John", EntityOperation.CREATE);

        // Assert
        var svc = new NotificationService();
        var notification = svc.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Contains("John", notification.Message);
    }

    [Fact]
    public void SendEntityNotification_WithoutDisplayName_EnqueuesNotification()
    {
        // Act
        _controller.CallSendEntityNotification("Course", "101", EntityOperation.DELETE);

        // Assert
        var svc = new NotificationService();
        var notification = svc.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course", notification.EntityType);
        Assert.Contains("ID: 101", notification.Message);
    }

    [Fact]
    public void SendEntityNotification_DoesNotThrow_OnException()
    {
        // The SendEntityNotification catches exceptions - verify it doesn't propagate
        // This is a basic test since NotificationService itself is robust
        var exception = Record.Exception(() =>
            _controller.CallSendEntityNotification("Test", "1", EntityOperation.UPDATE));

        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DisposesContextAndService()
    {
        // Arrange
        var ctx = TestDbContextFactory.Create();
        var controller = new TestableController(ctx);

        // Act & Assert - should not throw
        var exception = Record.Exception(() => controller.Dispose());
        Assert.Null(exception);
    }
}

